-- mod-subclass: the other head's left hand glows while she casts. One hidden aura per
-- precast hand glow of her spell copies, and which glow each copy shows.

DROP TABLE IF EXISTS `mod_subclass_other_head_glow`;
CREATE TABLE `mod_subclass_other_head_glow` (
    `ShownId` INT UNSIGNED NOT NULL,
    `GlowId` INT UNSIGNED NOT NULL,
    PRIMARY KEY (`ShownId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DELETE FROM `mod_subclass_other_head_glow`;

